package com.npcpermadeath;

import lombok.Value;

/**
 * One NPC type in one map region (a 64x64 tile chunk). Kill counts are kept
 * per area so that killing goblins in Lumbridge does not hide goblins in the
 * Goblin Village.
 */
@Value
public class AreaKey
{
	String name;
	int region;

	String serialize()
	{
		return region + "/" + name;
	}

	/**
	 * @return the parsed key, or null when the text is not a serialized key
	 */
	static AreaKey parse(String text)
	{
		int slash = text.indexOf('/');
		if (slash <= 0 || slash == text.length() - 1)
		{
			return null;
		}
		try
		{
			return new AreaKey(text.substring(slash + 1), Integer.parseInt(text.substring(0, slash)));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.npcpermadeath;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines map chunks on the world map: green where nothing has been
 * killed, orange where something has, red where every NPC type is gone.
 * Hovering a chunk shows every NPC type in it with kills and totals in a
 * panel pinned beside the chunk, so it stays clear of the map's own
 * tooltips.
 */
class ChunkMapOverlay extends Overlay
{
	static final int CHUNK_TILES = 64;

	enum State
	{
		NONE(new Color(70, 200, 90, 110), 1f),
		SOME(new Color(255, 160, 40, 230), 2f),
		ALL(new Color(235, 50, 50, 240), 2f);

		final Color color;
		final float stroke;

		State(Color color, float stroke)
		{
			this.color = color;
			this.stroke = stroke;
		}
	}

	/** One NPC type in a chunk. */
	@Value
	static class Entry
	{
		String name;
		int kills;
		/** Known spawns, or null. */
		Integer total;
	}

	/** What the plugin knows about chunks; called on the client thread while rendering. */
	interface ChunkSource
	{
		boolean isKnown(int region);

		State state(int region);

		String heading(int region);

		List<Entry> entries(int region);
	}

	/** Beyond this many chunks in view, only chunks with kills are drawn. */
	private static final int MAX_FULL_GRID = 2500;

	private final Client client;
	private final ChunkSource source;
	/** Chunk under the mouse this frame, or -1; read by {@link ChunkPanelOverlay}. */
	private int hoveredRegion = -1;
	private Rectangle hoveredRect;
	private Rectangle mapBounds;

	ChunkMapOverlay(NpcPermadeathPlugin plugin, Client client, ChunkSource source)
	{
		super(plugin);
		this.client = client;
		this.source = source;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.Worldmap.MAP_CONTAINER >>> 16);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		hoveredRegion = -1;
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || map.isHidden())
		{
			return null;
		}
		Rectangle bounds = map.getBounds();
		WorldMap worldMap = client.getWorldMap();
		Point centre = worldMap.getWorldMapPosition();
		double pxPerTile = worldMap.getWorldMapZoom();
		if (centre == null || pxPerTile <= 0)
		{
			return null;
		}
		mapBounds = bounds;
		// The map widget's centre shows the world tile the map is positioned on.
		double originX = bounds.getCenterX() - centre.getX() * pxPerTile;
		double originY = bounds.getCenterY() + centre.getY() * pxPerTile;
		// World tile range currently on screen (y grows upward on the map).
		int minTileX = (int) Math.floor((bounds.x - originX) / pxPerTile);
		int maxTileX = (int) Math.ceil((bounds.x + bounds.width - originX) / pxPerTile);
		int minTileY = (int) Math.floor((originY - (bounds.y + bounds.height)) / pxPerTile);
		int maxTileY = (int) Math.ceil((originY - bounds.y) / pxPerTile);
		int rx0 = Math.max(0, minTileX >> 6);
		int rx1 = Math.min(255, maxTileX >> 6);
		int ry0 = Math.max(0, minTileY >> 6);
		int ry1 = Math.min(255, maxTileY >> 6);
		boolean fullGrid = (long) (rx1 - rx0 + 1) * (ry1 - ry0 + 1) <= MAX_FULL_GRID;

		Shape oldClip = g.getClip();
		g.setClip(bounds);
		Point mouse = client.getMouseCanvasPosition();
		int hovered = -1;
		Rectangle hoveredRect = null;
		for (int rx = rx0; rx <= rx1; rx++)
		{
			for (int ry = ry0; ry <= ry1; ry++)
			{
				int region = (rx << 8) | ry;
				if (!source.isKnown(region))
				{
					continue;
				}
				State state = source.state(region);
				if (!fullGrid && state == State.NONE)
				{
					continue;
				}
				int px = (int) Math.round(originX + (rx << 6) * pxPerTile);
				int py = (int) Math.round(originY - ((ry << 6) + CHUNK_TILES) * pxPerTile);
				int size = (int) Math.round(CHUNK_TILES * pxPerTile);
				Rectangle rect = new Rectangle(px, py, size, size);
				if (!rect.intersects(bounds))
				{
					continue;
				}
				g.setColor(state.color);
				g.setStroke(new BasicStroke(state.stroke));
				g.draw(rect);
				if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()) && rect.contains(mouse.getX(), mouse.getY()))
				{
					hovered = region;
					hoveredRect = rect;
				}
			}
		}
		if (hovered >= 0)
		{
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(2f));
			g.draw(hoveredRect);
			this.hoveredRegion = hovered;
			this.hoveredRect = hoveredRect;
		}
		g.setClip(oldClip);
		return null;
	}

	int getHoveredRegion()
	{
		return hoveredRegion;
	}

	Rectangle getHoveredRect()
	{
		return hoveredRect;
	}

	Rectangle getMapBounds()
	{
		return mapBounds;
	}

	ChunkSource getSource()
	{
		return source;
	}
}

package com.npcpermadeath;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The list for the chunk the mouse is over on the world map, pinned beside
 * the chunk. Drawn above every widget so map markers cannot cover it.
 */
class ChunkPanelOverlay extends Overlay
{
	private static final int MAX_PANEL_LINES = 30;
	private static final int PANEL_GAP = 8;
	private static final Color UNTOUCHED = new Color(170, 170, 170);

	private final ChunkMapOverlay mapOverlay;
	private final PanelComponent panel = new PanelComponent();

	ChunkPanelOverlay(NpcPermadeathPlugin plugin, ChunkMapOverlay mapOverlay)
	{
		super(plugin);
		this.mapOverlay = mapOverlay;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panel.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		int region = mapOverlay.getHoveredRegion();
		Rectangle chunk = mapOverlay.getHoveredRect();
		Rectangle bounds = mapOverlay.getMapBounds();
		if (region < 0 || chunk == null || bounds == null)
		{
			return null;
		}
		ChunkMapOverlay.ChunkSource source = mapOverlay.getSource();
		panel.getChildren().clear();
		panel.getChildren().add(TitleComponent.builder().text(source.heading(region)).color(Color.WHITE).build());
		List<ChunkMapOverlay.Entry> entries = source.entries(region);
		int shown = Math.min(entries.size(), MAX_PANEL_LINES);
		for (int i = 0; i < shown; i++)
		{
			ChunkMapOverlay.Entry e = entries.get(i);
			String count = e.getTotal() == null ? Integer.toString(e.getKills()) : e.getKills() + " / " + e.getTotal();
			Color color = e.getKills() == 0 ? UNTOUCHED
				: e.getTotal() != null && e.getKills() >= e.getTotal()
					? ChunkMapOverlay.State.ALL.color
					: ChunkMapOverlay.State.SOME.color;
			panel.getChildren().add(LineComponent.builder()
				.left(e.getName()).leftColor(e.getKills() == 0 ? UNTOUCHED : Color.WHITE)
				.right(count).rightColor(color)
				.build());
		}
		if (entries.size() > shown)
		{
			panel.getChildren().add(LineComponent.builder().left("+" + (entries.size() - shown) + " more").build());
		}

		// Measure first with an empty clip, then place beside the chunk and draw for real.
		Shape clip = g.getClip();
		g.setClip(new Rectangle(0, 0, 0, 0));
		panel.setPreferredLocation(new java.awt.Point(0, 0));
		Dimension size = panel.render(g);
		g.setClip(clip);
		if (size == null)
		{
			return null;
		}
		int x = chunk.x + chunk.width + PANEL_GAP;
		if (x + size.width > bounds.x + bounds.width)
		{
			x = chunk.x - PANEL_GAP - size.width;
		}
		int y = Math.max(bounds.y, Math.min(chunk.y, bounds.y + bounds.height - size.height));
		panel.setPreferredLocation(new java.awt.Point(x, y));
		panel.render(g);
		return null;
	}
}

package com.npcpermadeath;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Keeps the bundled data files fresh between plugin releases. A scheduled
 * job in the plugin repository regenerates them weekly; this fetches the
 * latest copy from GitHub once a week and caches it under the RuneLite
 * directory. Only data is fetched, never code.
 */
@Slf4j
class DataUpdater
{
	static final long REFRESH_MS = 7L * 24 * 60 * 60 * 1000;
	static final String KEY_PREFIX = "fetched.";
	private static final HttpUrl BASE = HttpUrl.parse(
		"https://raw.githubusercontent.com/Dewdul/npc-permadeath/master/src/main/resources/com/npcpermadeath/");
	private static final File DIR = new File(RuneLite.RUNELITE_DIR, "npc-permadeath");

	private final OkHttpClient httpClient;
	private final ConfigManager configManager;
	private final ClientThread clientThread;
	private final Set<String> inFlight = new HashSet<>();

	DataUpdater(OkHttpClient httpClient, ConfigManager configManager, ClientThread clientThread)
	{
		this.httpClient = httpClient;
		this.configManager = configManager;
		this.clientThread = clientThread;
	}

	/** The cached copy of a data file, or null if none has been fetched yet. */
	byte[] cached(String fileName)
	{
		File file = new File(DIR, fileName);
		if (!file.isFile())
		{
			return null;
		}
		try
		{
			return Files.readAllBytes(file.toPath());
		}
		catch (IOException e)
		{
			log.warn("Could not read cached {}", fileName, e);
			return null;
		}
	}

	/**
	 * Fetches the file if the cached copy is a week old or missing. The
	 * callback runs on the client thread, only when the content changed.
	 */
	void refreshIfStale(String fileName, long now, Consumer<byte[]> onChanged)
	{
		String key = KEY_PREFIX + fileName;
		Long fetched = configManager.getConfiguration(NpcPermadeathConfig.GROUP, key, Long.class);
		if (fetched != null && now - fetched < REFRESH_MS && new File(DIR, fileName).isFile())
		{
			return;
		}
		if (!inFlight.add(fileName))
		{
			return;
		}
		HttpUrl url = BASE.newBuilder().addPathSegment(fileName).build();
		httpClient.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Could not refresh {}", fileName, e);
				clientThread.invoke(() -> inFlight.remove(fileName));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				byte[] body = null;
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						body = r.body().bytes();
					}
				}
				catch (IOException e)
				{
					log.debug("Could not read refreshed {}", fileName, e);
				}
				byte[] fresh = body;
				clientThread.invoke(() ->
				{
					inFlight.remove(fileName);
					if (fresh == null || fresh.length == 0)
					{
						return;
					}
					configManager.setConfiguration(NpcPermadeathConfig.GROUP, key, now);
					byte[] previous = cached(fileName);
					if (previous != null && Arrays.equals(previous, fresh))
					{
						return;
					}
					if (store(fileName, fresh))
					{
						log.debug("Refreshed {} ({} bytes)", fileName, fresh.length);
						onChanged.accept(fresh);
					}
				});
			}
		});
	}

	private static boolean store(String fileName, byte[] content)
	{
		try
		{
			if (!DIR.isDirectory() && !DIR.mkdirs())
			{
				return false;
			}
			File tmp = new File(DIR, fileName + ".tmp");
			Files.write(tmp.toPath(), content);
			Files.move(tmp.toPath(), new File(DIR, fileName).toPath(), StandardCopyOption.REPLACE_EXISTING);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Could not store {}", fileName, e);
			return false;
		}
	}
}

package com.npcpermadeath;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.Predicate;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Draws translucent ghost copies of hidden NPCs. A ghost is a client-side
 * scene object that follows its NPC, so it has no menu entries and can be
 * neither clicked, attacked nor looted. The real NPC stays hidden.
 *
 * <p>Everything here touches the client and must run on the client thread.
 * Ghosts are created and removed when an NPC's hidden state changes; the only
 * per-frame work is moving the ghosts that already exist.
 */
@Slf4j
class GhostManager
{
	private static final int MAX_CACHED_MODELS = 64;
	private static final int MAX_CACHED_ANIMATIONS = 128;
	/** Model scale value that means "unscaled". */
	private static final int NORMAL_SCALE = 128;
	/** Pale spectral blue-white, packed as the game's 16 bit HSL. */
	private static final short TINT_COLOUR = JagexColor.packHSL(40, 2, 112);

	/** What makes one ghost model different from another. */
	@Value
	static class ModelKey
	{
		int compositionId;
		int alpha;
		boolean tint;
	}

	private final Client client;
	private final NpcPermadeathConfig config;
	private final Map<NPC, Ghost> ghosts = new IdentityHashMap<>();
	private final Map<ModelKey, Model> models = lruMap(MAX_CACHED_MODELS);
	private final Map<Integer, Animation> animations = lruMap(MAX_CACHED_ANIMATIONS);

	GhostManager(Client client, NpcPermadeathConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/**
	 * Brings one NPC's ghost in line with whether it is hidden: creates it,
	 * rebuilds it if the NPC changed form, or removes it.
	 */
	void sync(NPC npc, boolean hidden)
	{
		if (!hidden || !config.ghosts())
		{
			remove(npc);
			return;
		}
		NPCComposition composition = compositionOf(npc);
		if (composition == null)
		{
			remove(npc);
			return;
		}
		Ghost ghost = ghosts.get(npc);
		if (ghost != null && ghost.compositionId == composition.getId())
		{
			return;
		}
		Model model = modelFor(composition);
		if (model == null)
		{
			remove(npc);
			return;
		}
		if (ghost == null)
		{
			ghost = new Ghost(client, npc);
			ghosts.put(npc, ghost);
		}
		ghost.setBase(model, composition.getId());
		ghost.follow();
		ghost.mirrorAnimation(this::animation);
	}

	void remove(NPC npc)
	{
		Ghost ghost = ghosts.remove(npc);
		if (ghost != null)
		{
			ghost.unregister();
		}
	}

	/** Re-checks every NPC in the scene and every existing ghost against the hidden test. */
	void resync(Iterable<? extends NPC> scene, Predicate<NPC> isHidden)
	{
		if (!config.ghosts())
		{
			clear();
			return;
		}
		for (NPC npc : new ArrayList<>(ghosts.keySet()))
		{
			if (!isHidden.test(npc))
			{
				remove(npc);
			}
		}
		for (NPC npc : scene)
		{
			sync(npc, isHidden.test(npc));
		}
	}

	/** Throws away every ghost and cached model and builds them again, for example after a setting changed. */
	void rebuildAll(Iterable<? extends NPC> scene, Predicate<NPC> isHidden)
	{
		ArrayList<NPC> known = new ArrayList<>(ghosts.keySet());
		clear();
		if (!config.ghosts())
		{
			return;
		}
		// Ghosts of NPCs outside the top level scene (boats) are not in the scan, so rebuild them too.
		for (NPC npc : known)
		{
			sync(npc, isHidden.test(npc));
		}
		for (NPC npc : scene)
		{
			sync(npc, isHidden.test(npc));
		}
	}

	/** Runs every client tick: moves each ghost to where its NPC is and copies its animation. */
	void update()
	{
		if (ghosts.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Iterator<Ghost> it = ghosts.values().iterator();
		while (it.hasNext())
		{
			Ghost ghost = it.next();
			if (!ghost.npcStillInScene())
			{
				ghost.unregister();
				it.remove();
				continue;
			}
			ghost.follow();
			ghost.mirrorAnimation(this::animation);
		}
	}

	/** Removes every ghost and forgets the cached models. */
	void clear()
	{
		for (Ghost ghost : ghosts.values())
		{
			ghost.unregister();
		}
		ghosts.clear();
		models.clear();
		animations.clear();
	}

	private static NPCComposition compositionOf(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		return composition != null ? composition : npc.getComposition();
	}

	private Animation animation(int id)
	{
		Animation cached = animations.get(id);
		if (cached == null)
		{
			cached = client.loadAnimation(id);
			if (cached != null)
			{
				animations.put(id, cached);
			}
		}
		return cached;
	}

	private Model modelFor(NPCComposition composition)
	{
		ModelKey key = new ModelKey(composition.getId(), opacityToAlpha(config.ghostOpacity()), config.ghostTint());
		Model model = models.get(key);
		if (model == null)
		{
			model = build(composition, key);
			if (model != null)
			{
				models.put(key, model);
			}
		}
		return model;
	}

	/** Builds the translucent model for an NPC type the same way the game builds the NPC itself. */
	private Model build(NPCComposition composition, ModelKey key)
	{
		int[] ids = composition.getModels();
		if (ids == null || ids.length == 0)
		{
			return null;
		}
		ModelData[] parts = new ModelData[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			parts[i] = client.loadModelData(ids[i]);
			if (parts[i] == null)
			{
				log.debug("No model {} for NPC {}", ids[i], composition.getId());
				return null;
			}
		}
		ModelData merged = parts.length == 1 ? parts[0] : client.mergeModels(parts);
		if (merged == null)
		{
			return null;
		}
		// Loaded model data shares its arrays with the game's own models, so
		// take private copies of everything we are about to change first.
		ModelData data = merged.shallowCopy().cloneColors();

		short[] from = composition.getColorToReplace();
		short[] to = composition.getColorToReplaceWith();
		if (from != null && to != null)
		{
			for (int i = 0; i < Math.min(from.length, to.length); i++)
			{
				data.recolor(from[i], to[i]);
			}
		}

		int width = composition.getWidthScale();
		int height = composition.getHeightScale();
		if (width != NORMAL_SCALE || height != NORMAL_SCALE)
		{
			data.cloneVertices().scale(width, height, width);
		}

		// Passing true makes the call create the array when the model has none.
		data.cloneTransparencies(true);
		byte[] faces = data.getFaceTransparencies();
		if (faces != null)
		{
			for (int i = 0; i < faces.length; i++)
			{
				faces[i] = combineAlpha(faces[i], key.getAlpha());
			}
		}

		if (key.isTint())
		{
			short[] colours = data.getFaceColors();
			if (colours != null)
			{
				Arrays.fill(colours, TINT_COLOUR);
			}
		}
		return data.light();
	}

	/**
	 * Face transparency as the game stores it: 0 is opaque and 255 is fully
	 * transparent (the GPU plugin draws the face with alpha 255 minus this).
	 * The ghost's setting never makes a face more solid than it already was,
	 * so invisible helper faces some models carry stay invisible.
	 */
	static byte opacityToAlpha(int opacityPercent)
	{
		int percent = Math.max(0, Math.min(100, opacityPercent));
		return (byte) Math.round((100 - percent) * 255 / 100f);
	}

	/** The more transparent of a face's own transparency and the ghost's, as an unsigned byte. */
	static byte combineAlpha(byte existing, int ghostAlpha)
	{
		return (byte) Math.max(existing & 0xff, ghostAlpha & 0xff);
	}

	/** A map that drops its least recently used entry once it holds more than max. */
	static <K, V> Map<K, V> lruMap(int max)
	{
		return new LinkedHashMap<K, V>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<K, V> eldest)
			{
				return size() > max;
			}
		};
	}

	/** One ghost: a scene object that draws the cached model, posed like the NPC it follows. */
	private static final class Ghost extends RuneLiteObjectController
	{
		private final Client client;
		private final NPC npc;
		private Model base;
		private int compositionId = -1;
		private boolean registered;
		private AnimationController pose;
		private AnimationController action;
		private int poseId = -1;
		private int actionId = -1;
		private int lastActionFrame;

		Ghost(Client client, NPC npc)
		{
			this.client = client;
			this.npc = npc;
		}

		void setBase(Model model, int compositionId)
		{
			this.base = model;
			this.compositionId = compositionId;
		}

		@Override
		public Model getModel()
		{
			if (action != null && action.getAnimation() != null)
			{
				return action.animate(base, pose != null && pose.getAnimation() != null ? pose : null);
			}
			if (pose != null && pose.getAnimation() != null)
			{
				return pose.animate(base);
			}
			return base;
		}

		/** The client calls this as time passes, so animations run without any work from us. */
		@Override
		public void tick(int cycles)
		{
			if (pose != null)
			{
				pose.tick(cycles);
			}
			if (action != null)
			{
				action.tick(cycles);
			}
		}

		boolean npcStillInScene()
		{
			WorldView view = npc.getWorldView();
			return view != null && view.npcs().byIndex(npc.getIndex()) == npc;
		}

		/** Copies the NPC's position, plane and facing, and makes sure the object is registered. */
		void follow()
		{
			LocalPoint point = npc.getLocalLocation();
			WorldView view = npc.getWorldView();
			if (point == null || view == null)
			{
				return;
			}
			int plane = view.getPlane();
			// An object must be re-registered when it moves between world views.
			if (registered && point.getWorldView() != getWorldView())
			{
				unregister();
			}
			setLocation(point, plane);
			setZ(Perspective.getTileHeight(client, point, plane));
			setOrientation(npc.getCurrentOrientation());
			if (!registered)
			{
				client.registerRuneLiteObject(this);
				registered = true;
			}
		}

		void unregister()
		{
			if (registered)
			{
				client.removeRuneLiteObject(this);
				registered = false;
			}
		}

		/** Follows the NPC's idle, walk and action animations, restarting the action when the NPC does. */
		void mirrorAnimation(IntFunction<Animation> loader)
		{
			int newPose = npc.getPoseAnimation();
			if (newPose != poseId)
			{
				poseId = newPose;
				pose = controller(newPose, loader);
			}
			int newAction = npc.getAnimation();
			int frame = npc.getAnimationFrame();
			if (newAction != actionId)
			{
				actionId = newAction;
				action = controller(newAction, loader);
			}
			else if (action != null && frame < lastActionFrame)
			{
				action.reset();
			}
			lastActionFrame = frame;
		}

		private AnimationController controller(int id, IntFunction<Animation> loader)
		{
			if (id < 0)
			{
				return null;
			}
			Animation animation = loader.apply(id);
			return animation == null ? null : new AnimationController(client, animation);
		}
	}
}

package com.npcpermadeath;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import lombok.Value;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;

/**
 * Watches ground item spawns for two purposes: deciding whether a kill was
 * the player's (their loot appeared on the NPC's tile) and, for hidden NPCs,
 * hiding that loot without touching other items on the tile.
 *
 * <p>Loot appears on the NPC's tile on the same tick the dead NPC despawns,
 * sometimes before and sometimes after the despawn event, so recent item
 * spawns are buffered for a few ticks and looked up by tile.
 */
class LootWatcher
{
	/** How far apart (in ticks) a despawn and its loot may be. */
	static final int WINDOW_TICKS = 1;
	private static final int KEEP_TICKS = 3;

	@Value
	private static class Spawn
	{
		TileItem item;
		WorldPoint tile;
		Point scene;
		int tick;
		boolean mine;
	}

	private final List<Spawn> recent = new ArrayList<>();
	private final Map<WorldPoint, Integer> armedTiles = new HashMap<>();
	/** Cursed items and the scene coordinates of their tile. */
	private final Map<TileItem, Point> cursed = new IdentityHashMap<>();

	void onItemSpawned(TileItem item, WorldPoint tile, Point scene, int tick)
	{
		if (tile == null || scene == null)
		{
			return;
		}
		boolean mine = item.getOwnership() == TileItem.OWNERSHIP_SELF;
		recent.add(new Spawn(item, tile, scene, tick, mine));
		Integer armed = armedTiles.get(tile);
		if (armed != null && tick - armed <= WINDOW_TICKS)
		{
			cursed.put(item, scene);
		}
	}

	void onItemDespawned(TileItem item)
	{
		cursed.remove(item);
	}

	/** Whether any item appeared on the tile around the given tick. */
	boolean sawLoot(WorldPoint tile, int tick)
	{
		return recent.stream().anyMatch(s -> s.getTile().equals(tile) && Math.abs(s.getTick() - tick) <= WINDOW_TICKS);
	}

	/** Whether an item owned by the player appeared on the tile around the given tick. */
	boolean sawMyLoot(WorldPoint tile, int tick)
	{
		return recent.stream().anyMatch(s -> s.isMine() && s.getTile().equals(tile)
			&& Math.abs(s.getTick() - tick) <= WINDOW_TICKS);
	}

	/** A hidden NPC died on this tile; anything that drops there now is its loot. */
	void armTile(WorldPoint tile, int tick)
	{
		if (tile == null)
		{
			return;
		}
		armedTiles.put(tile, tick);
		for (Spawn spawn : recent)
		{
			if (spawn.getTile().equals(tile) && Math.abs(spawn.getTick() - tick) <= WINDOW_TICKS)
			{
				cursed.put(spawn.getItem(), spawn.getScene());
			}
		}
	}

	boolean isCursed(Renderable renderable)
	{
		return renderable instanceof TileItem && cursed.containsKey(renderable);
	}

	/** Whether a ground-item menu entry for this item on this scene tile should be removed. */
	boolean blocksMenu(int itemId, int sceneX, int sceneY)
	{
		for (Map.Entry<TileItem, Point> entry : cursed.entrySet())
		{
			Point p = entry.getValue();
			if (entry.getKey().getId() == itemId && p.getX() == sceneX && p.getY() == sceneY)
			{
				return true;
			}
		}
		return false;
	}

	int cursedCount()
	{
		return cursed.size();
	}

	void tick(int tick)
	{
		Iterator<Spawn> it = recent.iterator();
		while (it.hasNext())
		{
			if (tick - it.next().getTick() > KEEP_TICKS)
			{
				it.remove();
			}
		}
		armedTiles.values().removeIf(t -> tick - t > WINDOW_TICKS);
	}

	void clear()
	{
		recent.clear();
		armedTiles.clear();
		cursed.clear();
	}
}

package com.npcpermadeath;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.BiFunction;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One editable list of NPC names for the sidebar panel: a text field with a
 * suggestion list under it, and the current entries with a remove button each.
 *
 * <p>The suggestions are an inline list rather than a popup, so the text field
 * keeps the keyboard focus the whole time. Everything here runs on the Swing
 * thread.
 */
class NameFilterEditor extends JPanel
{
	/** The most suggestions shown at once. */
	static final int MAX_SUGGESTIONS = 8;
	private static final int ROW_HEIGHT = 18;
	/** Width the description wraps at, to fit the sidebar. */
	private static final int TEXT_WIDTH = 170;

	private final BiFunction<String, Integer, List<String>> suggestions;
	private final Consumer<List<String>> onChange;
	private final String emptyText;
	private final JTextField field = new JTextField();
	private final DefaultListModel<String> model = new DefaultListModel<>();
	private final JList<String> suggestionList = new JList<>(model);
	private final JPanel entryRows = new JPanel(new GridLayout(0, 1, 0, 2));
	private List<String> entries = Collections.emptyList();

	/**
	 * @param suggestions names matching the typed text, given the text and a limit
	 * @param onChange called with the new entries after the user adds or removes one
	 */
	NameFilterEditor(String title, String description, String emptyText,
		BiFunction<String, Integer, List<String>> suggestions, Consumer<List<String>> onChange)
	{
		this.suggestions = suggestions;
		this.onChange = onChange;
		this.emptyText = emptyText;
		setLayout(new GridBagLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel heading = new JLabel(title);
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stack(this, heading, 0);

		JLabel hint = new JLabel("<html><body style='width:" + TEXT_WIDTH + "px'>" + description + "</body></html>");
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stack(this, hint, 2);

		field.setFont(FontManager.getRunescapeSmallFont());
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(3, 5, 3, 5)));
		field.setToolTipText("Type a name, or a wildcard such as Cow*, then press Enter");
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refreshSuggestions();
			}
		});
		field.addActionListener(e -> commit());
		field.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_DOWN:
						moveSelection(1);
						e.consume();
						break;
					case KeyEvent.VK_UP:
						moveSelection(-1);
						e.consume();
						break;
					case KeyEvent.VK_ESCAPE:
						hideSuggestions();
						e.consume();
						break;
					default:
						break;
				}
			}
		});
		stack(this, field, 4);

		suggestionList.setFocusable(false);
		suggestionList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		suggestionList.setFixedCellHeight(ROW_HEIGHT);
		suggestionList.setFont(FontManager.getRunescapeSmallFont());
		suggestionList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		suggestionList.setForeground(Color.WHITE);
		suggestionList.setSelectionBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
		suggestionList.setSelectionForeground(ColorScheme.BRAND_ORANGE);
		suggestionList.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		suggestionList.setVisible(false);
		suggestionList.addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int row = rowAt(e);
				if (row >= 0)
				{
					suggestionList.setSelectedIndex(row);
				}
			}
		});
		suggestionList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int row = rowAt(e);
				if (row >= 0)
				{
					addEntry(model.get(row));
				}
			}
		});
		stack(this, suggestionList, 0);

		entryRows.setBackground(ColorScheme.DARK_GRAY_COLOR);
		stack(this, entryRows, 4);
		rebuildEntries();
	}

	/** Adds a full-width component under the previous ones. */
	static void stack(JPanel parent, JComponent child, int topGap)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = parent.getComponentCount();
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTHWEST;
		c.insets = new Insets(topGap, 0, 0, 0);
		parent.add(child, c);
	}

	/** Shows the entries held in the config, e.g. after the settings page changed them. */
	void setEntries(List<String> newEntries)
	{
		if (entries.equals(newEntries))
		{
			return;
		}
		entries = newEntries;
		rebuildEntries();
		refreshSuggestions();
	}

	List<String> getEntries()
	{
		return entries;
	}

	private int rowAt(MouseEvent e)
	{
		int row = suggestionList.locationToIndex(e.getPoint());
		return row >= 0 && suggestionList.getCellBounds(row, row).contains(e.getPoint()) ? row : -1;
	}

	/** Enter: the highlighted suggestion if there is one, otherwise exactly what was typed. */
	private void commit()
	{
		int row = suggestionList.getSelectedIndex();
		addEntry(row >= 0 ? model.get(row) : field.getText());
	}

	private void addEntry(String text)
	{
		field.setText("");
		List<String> next = NameList.add(entries, text);
		if (next != entries)
		{
			entries = next;
			rebuildEntries();
			onChange.accept(entries);
		}
	}

	private void removeEntry(String entry)
	{
		List<String> next = NameList.remove(entries, entry);
		if (next != entries)
		{
			entries = next;
			rebuildEntries();
			refreshSuggestions();
			onChange.accept(entries);
		}
	}

	private void moveSelection(int delta)
	{
		if (model.isEmpty())
		{
			return;
		}
		int row = Math.max(-1, Math.min(model.size() - 1, suggestionList.getSelectedIndex() + delta));
		if (row < 0)
		{
			suggestionList.clearSelection();
		}
		else
		{
			suggestionList.setSelectedIndex(row);
		}
	}

	private void hideSuggestions()
	{
		model.clear();
		suggestionList.setVisible(false);
		revalidate();
		repaint();
	}

	private void refreshSuggestions()
	{
		List<String> matches = new ArrayList<>();
		String typed = field.getText();
		if (!typed.trim().isEmpty())
		{
			// Ask for extra so that names already listed can be skipped.
			for (String name : suggestions.apply(typed, MAX_SUGGESTIONS + entries.size()))
			{
				if (matches.size() < MAX_SUGGESTIONS && !NameList.contains(entries, name))
				{
					matches.add(name);
				}
			}
		}
		model.clear();
		matches.forEach(model::addElement);
		suggestionList.setVisible(!matches.isEmpty());
		revalidate();
		repaint();
	}

	private void rebuildEntries()
	{
		entryRows.removeAll();
		if (entries.isEmpty())
		{
			JLabel none = new JLabel(emptyText);
			none.setFont(FontManager.getRunescapeSmallFont());
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			entryRows.add(none);
		}
		for (String entry : entries)
		{
			entryRows.add(entryRow(entry));
		}
		revalidate();
		repaint();
	}

	private JPanel entryRow(String entry)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 3));

		JLabel name = new JLabel(entry);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		name.setToolTipText(entry);
		row.add(name, BorderLayout.CENTER);

		JButton remove = new JButton("x");
		remove.setFont(FontManager.getRunescapeSmallFont());
		remove.setToolTipText("Remove " + entry);
		remove.setMargin(new Insets(0, 4, 0, 4));
		remove.setFocusPainted(false);
		remove.addActionListener(e -> removeEntry(entry));
		row.add(remove, BorderLayout.EAST);
		return row;
	}
}

package com.npcpermadeath;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Text;

/**
 * The comma-separated NPC name lists kept in the config ("Only these NPCs" and
 * "Never these NPCs"), as immutable lists. The panel and the settings page edit
 * the same text, so both go through here.
 */
final class NameList
{
	private NameList()
	{
	}

	/** Splits the config text into trimmed, non-empty entries. */
	static List<String> parse(String csv)
	{
		List<String> out = new ArrayList<>();
		for (String entry : Text.fromCSV(csv == null ? "" : csv))
		{
			String trimmed = entry.trim();
			if (!trimmed.isEmpty())
			{
				out.add(trimmed);
			}
		}
		return Collections.unmodifiableList(out);
	}

	/** The config text for the entries. */
	static String toCsv(List<String> entries)
	{
		return String.join(", ", entries);
	}

	/**
	 * Adds what was typed. Several names separated by commas are added one by
	 * one; blanks and entries already present (ignoring case) are skipped.
	 *
	 * @return a new list, or the same list when nothing was added
	 */
	static List<String> add(List<String> entries, String typed)
	{
		List<String> out = new ArrayList<>(entries);
		for (String candidate : parse(typed))
		{
			if (indexOf(out, candidate) < 0)
			{
				out.add(candidate);
			}
		}
		return out.size() == entries.size() ? entries : Collections.unmodifiableList(out);
	}

	/**
	 * @return a new list without the entry (ignoring case), or the same list
	 * when it was not there
	 */
	static List<String> remove(List<String> entries, String entry)
	{
		int at = indexOf(entries, entry.trim());
		if (at < 0)
		{
			return entries;
		}
		List<String> out = new ArrayList<>(entries);
		out.remove(at);
		return Collections.unmodifiableList(out);
	}

	static boolean contains(List<String> entries, String entry)
	{
		return indexOf(entries, entry.trim()) >= 0;
	}

	private static int indexOf(List<String> entries, String entry)
	{
		for (int i = 0; i < entries.size(); i++)
		{
			if (entries.get(i).equalsIgnoreCase(entry))
			{
				return i;
			}
		}
		return -1;
	}
}

package com.npcpermadeath;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.IntFunction;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPCComposition;
import net.runelite.client.util.Text;

/**
 * The NPC names offered by the filter type-ahead: every attackable NPC the game
 * client knows about, read from its own definitions a slice at a time, so the
 * list covers the whole game and stays current without a plugin update.
 *
 * <p>Until the scan finishes, the names from the bundled spawn data are
 * offered instead, together with the extra names (see {@link #setExtraNames}).
 * {@link #step} runs on the client thread; {@link #suggest} may be called from
 * any thread.
 *
 * <p>Multi-form NPCs need no special handling: each form is an NPC id of its
 * own, so every form is visited and judged by its own name and actions.
 */
@Slf4j
class NpcNameIndex
{
	/** The most ids looked at in one slice. */
	static final int SLICE_IDS = 1000;
	/** A slice also stops once it has run this long, so the client never stutters. */
	static final long SLICE_NANOS = 4_000_000L;
	/** The highest id in the API's NpcID table; the scan always covers at least this far. */
	static final int KNOWN_MAX_ID = 16575;
	/** Past the known maximum, the scan stops after this many ids in a row without a name. */
	static final int EMPTY_RUN_LIMIT = 1000;
	/** The scan never goes past this id, whatever the client reports. */
	static final int HARD_CAP_ID = 40000;

	/** An immutable, alphabetically sorted list of names with their lower-case forms. */
	private static final class Names
	{
		static final Names NONE = new Names(new TreeMap<>());

		final List<String> names;
		final List<String> lower;

		Names(TreeMap<String, String> byLowerCase)
		{
			names = Collections.unmodifiableList(new ArrayList<>(byLowerCase.values()));
			lower = Collections.unmodifiableList(new ArrayList<>(byLowerCase.keySet()));
		}
	}

	/** The seed and extra names together, offered until the scan has finished. */
	private volatile Names beforeScan = Names.NONE;
	/** The scanned names plus the extras that exist as NPCs; null until the scan has finished. */
	private volatile Names built;
	private volatile boolean cancelled;

	// Inputs behind the published lists; guarded by lock, since they are set from any thread.
	private final Object lock = new Object();
	private List<String> seedNames = Collections.emptyList();
	private List<String> extraNames = Collections.emptyList();
	/** The attackable names of the finished scan by lower case, or null while it is unfinished. */
	private Map<String, String> scannedNames;
	/** The lower-cased name of every definition the finished scan visited, or null. */
	private Set<String> seenNames;

	// Scan state, touched by the client thread only.
	private final TreeMap<String, String> found = new TreeMap<>();
	private final Set<String> seen = new HashSet<>();
	private int nextId;
	private int emptyRun;
	private boolean scanDone;

	/** Names to offer until the scan has finished. */
	void setSeedNames(Collection<String> names)
	{
		synchronized (lock)
		{
			seedNames = new ArrayList<>(names);
			publish();
		}
	}

	/**
	 * Names that are always on offer, such as boss names that have no static spawn
	 * and may lack an Attack action. Before the scan has finished they are all
	 * offered; afterwards only those that some NPC definition actually carries.
	 * Replaces any earlier extras.
	 */
	void setExtraNames(Collection<String> names)
	{
		synchronized (lock)
		{
			extraNames = new ArrayList<>(names);
			publish();
		}
	}

	/** Rebuilds the published lists from the inputs. Call with the lock held. */
	private void publish()
	{
		TreeMap<String, String> pre = new TreeMap<>();
		addAll(pre, seedNames);
		addAll(pre, extraNames);
		beforeScan = new Names(pre);
		if (scannedNames != null)
		{
			TreeMap<String, String> after = new TreeMap<>(scannedNames);
			for (String extra : extraNames)
			{
				if (seenNames.contains(extra.toLowerCase(Locale.ROOT)))
				{
					after.putIfAbsent(extra.toLowerCase(Locale.ROOT), extra);
				}
			}
			built = new Names(after);
		}
	}

	private static void addAll(TreeMap<String, String> byLowerCase, Collection<String> names)
	{
		for (String name : names)
		{
			byLowerCase.putIfAbsent(name.toLowerCase(Locale.ROOT), name);
		}
	}

	/** Stops the scan at the next slice. */
	void cancel()
	{
		cancelled = true;
	}

	/** Whether the full scan has finished and replaced the fallback names. */
	boolean isComplete()
	{
		return built != null;
	}

	/** How many names are on offer right now. */
	int size()
	{
		return current().names.size();
	}

	/**
	 * Looks at the next slice of NPC ids. Call again until it returns true.
	 *
	 * @param definitions the client's NPC definitions by id; may return null
	 * @return true once the scan is finished or cancelled
	 */
	boolean step(IntFunction<NPCComposition> definitions)
	{
		if (cancelled || scanDone)
		{
			return true;
		}
		long deadline = System.nanoTime() + SLICE_NANOS;
		for (int looked = 0; looked < SLICE_IDS; looked++)
		{
			if (nextId >= HARD_CAP_ID || nextId > KNOWN_MAX_ID && emptyRun >= EMPTY_RUN_LIMIT)
			{
				finish();
				return true;
			}
			visit(definitions, nextId++);
			if (looked % 50 == 49 && System.nanoTime() > deadline)
			{
				break;
			}
		}
		return false;
	}

	private void visit(IntFunction<NPCComposition> definitions, int id)
	{
		NPCComposition definition;
		try
		{
			definition = definitions.apply(id);
		}
		catch (RuntimeException e)
		{
			definition = null;
		}
		String name = definition == null ? null : cleanName(definition.getName());
		if (name == null)
		{
			emptyRun++;
			return;
		}
		emptyRun = 0;
		String lower = name.toLowerCase(Locale.ROOT);
		seen.add(lower);
		if (hasAttack(definition.getActions()))
		{
			found.putIfAbsent(lower, name);
		}
	}

	private void finish()
	{
		scanDone = true;
		if (!found.isEmpty())
		{
			synchronized (lock)
			{
				scannedNames = Collections.unmodifiableMap(new TreeMap<>(found));
				seenNames = Collections.unmodifiableSet(new HashSet<>(seen));
				publish();
			}
		}
		log.debug("Scanned {} NPC ids, {} attackable names, {} names in all", nextId, found.size(), seen.size());
	}

	/** The display name with tags removed, or null for the blank and "null" placeholders. */
	static String cleanName(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String name = Text.removeTags(raw).trim();
		return name.isEmpty() || "null".equalsIgnoreCase(name) ? null : name;
	}

	static boolean hasAttack(String[] actions)
	{
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Attack".equalsIgnoreCase(action))
				{
					return true;
				}
			}
		}
		return false;
	}

	private Names current()
	{
		Names scanned = built;
		return scanned != null ? scanned : beforeScan;
	}

	/** Up to limit names matching what was typed, best matches first. See {@link #rank}. */
	List<String> suggest(String typed, int limit)
	{
		Names names = current();
		return rank(names.names, names.lower, typed, limit);
	}

	/**
	 * Case-insensitive matches, in three tiers: names that start with the text,
	 * then names with a word that starts with it, then names that merely contain
	 * it. Each tier keeps the input order, so sorted input gives alphabetical
	 * tiers. Nothing is suggested for blank input.
	 *
	 * @param names sorted alphabetically
	 * @param lower the same names in lower case
	 */
	static List<String> rank(List<String> names, List<String> lower, String typed, int limit)
	{
		String needle = typed == null ? "" : typed.trim().toLowerCase(Locale.ROOT);
		if (needle.isEmpty() || limit <= 0)
		{
			return Collections.emptyList();
		}
		List<String> prefix = new ArrayList<>();
		List<String> wordStart = new ArrayList<>();
		List<String> substring = new ArrayList<>();
		for (int i = 0; i < names.size() && prefix.size() < limit; i++)
		{
			String candidate = lower.get(i);
			int at = candidate.indexOf(needle);
			if (at < 0)
			{
				continue;
			}
			if (at == 0)
			{
				prefix.add(names.get(i));
			}
			else if (startsWord(candidate, needle))
			{
				if (wordStart.size() < limit)
				{
					wordStart.add(names.get(i));
				}
			}
			else if (substring.size() < limit)
			{
				substring.add(names.get(i));
			}
		}
		List<String> out = new ArrayList<>(prefix);
		out.addAll(wordStart);
		out.addAll(substring);
		return out.size() > limit ? new ArrayList<>(out.subList(0, limit)) : out;
	}

	/** Whether the needle occurs right after a space, dash, quote or other non-letter. */
	private static boolean startsWord(String candidate, String needle)
	{
		for (int at = candidate.indexOf(needle); at >= 0; at = candidate.indexOf(needle, at + 1))
		{
			if (at == 0 || !Character.isLetterOrDigit(candidate.charAt(at - 1)))
			{
				return true;
			}
		}
		return false;
	}
}

