package com.npcpermadeath;

import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class GhostManagerTest
{
	@Test
	public void opacityMapsToTheGameAlphaByte()
	{
		// In the game 0 is opaque and 255 is fully transparent.
		Assert.assertEquals(0, GhostManager.opacityToAlpha(100) & 0xff);
		Assert.assertEquals(255, GhostManager.opacityToAlpha(0) & 0xff);
		Assert.assertEquals(166, GhostManager.opacityToAlpha(35) & 0xff);
		Assert.assertEquals(230, GhostManager.opacityToAlpha(10) & 0xff);
		Assert.assertEquals(51, GhostManager.opacityToAlpha(80) & 0xff);
	}

	@Test
	public void higherOpacityIsAlwaysMoreSolid()
	{
		int previous = 256;
		for (int percent = 0; percent <= 100; percent++)
		{
			int alpha = GhostManager.opacityToAlpha(percent) & 0xff;
			Assert.assertTrue(alpha <= previous);
			previous = alpha;
		}
	}

	@Test
	public void opacityOutsideTheRangeIsClamped()
	{
		Assert.assertEquals(255, GhostManager.opacityToAlpha(-20) & 0xff);
		Assert.assertEquals(0, GhostManager.opacityToAlpha(500) & 0xff);
	}

	@Test
	public void facesNeverBecomeMoreSolidThanTheyWere()
	{
		// An invisible helper face (255) stays invisible, and an opaque one takes the ghost's alpha.
		Assert.assertEquals(255, GhostManager.combineAlpha((byte) 255, 166) & 0xff);
		Assert.assertEquals(166, GhostManager.combineAlpha((byte) 0, 166) & 0xff);
		Assert.assertEquals(200, GhostManager.combineAlpha((byte) 200, 166) & 0xff);
	}

	@Test
	public void modelKeysAreEqualOnlyForTheSameBuild()
	{
		GhostManager.ModelKey key = new GhostManager.ModelKey(7, 166, true);
		Assert.assertEquals(key, new GhostManager.ModelKey(7, 166, true));
		Assert.assertEquals(key.hashCode(), new GhostManager.ModelKey(7, 166, true).hashCode());
		Assert.assertNotEquals(key, new GhostManager.ModelKey(8, 166, true));
		Assert.assertNotEquals(key, new GhostManager.ModelKey(7, 165, true));
		Assert.assertNotEquals(key, new GhostManager.ModelKey(7, 166, false));
	}

	@Test
	public void lruMapDropsTheLeastRecentlyUsedEntry()
	{
		Map<Integer, String> map = GhostManager.lruMap(2);
		map.put(1, "a");
		map.put(2, "b");
		map.get(1);
		map.put(3, "c");
		Assert.assertTrue(map.containsKey(1));
		Assert.assertFalse(map.containsKey(2));
		Assert.assertTrue(map.containsKey(3));
		Assert.assertEquals(2, map.size());
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Point;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class LootWatcherTest
{
	private static final WorldPoint TILE = new WorldPoint(3245, 3245, 0);
	private static final WorldPoint OTHER_TILE = new WorldPoint(3246, 3245, 0);
	private static final Point SCENE = new Point(45, 45);

	private final LootWatcher loot = new LootWatcher();

	private static TileItem item(int id, int ownership)
	{
		return new FakeTileItem(id, ownership);
	}

	@Test
	public void myLootOnTheDeathTileIsRecognisedBeforeOrAfterTheDespawn()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_SELF), TILE, SCENE, 10);

		assertTrue(loot.sawLoot(TILE, 10));
		assertTrue(loot.sawMyLoot(TILE, 10));
		assertTrue(loot.sawMyLoot(TILE, 11));
		assertFalse(loot.sawMyLoot(TILE, 12));
		assertFalse(loot.sawMyLoot(OTHER_TILE, 10));
	}

	@Test
	public void someoneElsesLootIsLootButNotMine()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_OTHER), TILE, SCENE, 10);

		assertTrue(loot.sawLoot(TILE, 10));
		assertFalse(loot.sawMyLoot(TILE, 10));
	}

	@Test
	public void oldSpawnsAreForgotten()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_SELF), TILE, SCENE, 10);
		loot.tick(14);

		assertFalse(loot.sawLoot(TILE, 11));
	}

	@Test
	public void lootSpawnedAfterAHiddenDeathIsCursed()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.armTile(TILE, 10);
		loot.onItemSpawned(bones, TILE, SCENE, 10);

		assertTrue(loot.isCursed(bones));
		assertTrue(loot.blocksMenu(526, 45, 45));
		assertFalse(loot.blocksMenu(526, 46, 45));
		assertFalse(loot.blocksMenu(527, 45, 45));
	}

	@Test
	public void lootSpawnedJustBeforeTheDespawnEventIsCursed()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.onItemSpawned(bones, TILE, SCENE, 10);
		loot.armTile(TILE, 10);

		assertTrue(loot.isCursed(bones));
	}

	@Test
	public void unrelatedItemsOnTheTileStayUntouched()
	{
		TileItem old = item(526, TileItem.OWNERSHIP_NONE);
		loot.onItemSpawned(old, TILE, SCENE, 5);
		loot.tick(9);
		loot.armTile(TILE, 10);
		TileItem later = item(526, TileItem.OWNERSHIP_SELF);
		loot.onItemSpawned(later, TILE, SCENE, 13);

		assertFalse(loot.isCursed(old));
		assertFalse(loot.isCursed(later));
		assertEquals(0, loot.cursedCount());
	}

	@Test
	public void despawnedItemsAreForgotten()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.armTile(TILE, 10);
		loot.onItemSpawned(bones, TILE, SCENE, 10);

		loot.onItemDespawned(bones);

		assertFalse(loot.isCursed(bones));
		assertFalse(loot.blocksMenu(526, 45, 45));
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JList;
import javax.swing.JTextField;
import org.junit.Test;

/** Drives the editor the way the keyboard does, without showing it. */
public class NameFilterEditorTest
{
	private final List<List<String>> changes = new ArrayList<>();
	private final NpcNameIndex index = new NpcNameIndex();
	private final NameFilterEditor editor;
	private final JTextField field;
	private final JList<?> suggestionList;

	public NameFilterEditorTest()
	{
		index.setSeedNames(Arrays.asList("Cow", "Cow calf", "Goblin", "Giant rat", "Rat"));
		editor = new NameFilterEditor("Never", "d", "None.", index::suggest, changes::add);
		field = find(editor, JTextField.class);
		suggestionList = find(editor, JList.class);
	}

	private static <T extends Component> T find(Container root, Class<T> type)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				return type.cast(c);
			}
			if (c instanceof Container)
			{
				T inner = find((Container) c, type);
				if (inner != null)
				{
					return inner;
				}
			}
		}
		return null;
	}

	private static void collect(Container root, Class<? extends Component> type, List<Component> out)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				out.add(c);
			}
			if (c instanceof Container)
			{
				collect((Container) c, type, out);
			}
		}
	}

	private void press(int keyCode)
	{
		KeyEvent event = new KeyEvent(field, KeyEvent.KEY_PRESSED, 0, 0, keyCode, KeyEvent.CHAR_UNDEFINED);
		for (java.awt.event.KeyListener listener : field.getKeyListeners())
		{
			listener.keyPressed(event);
		}
	}

	@Test
	public void typingShowsSuggestionsAndEmptyTextHidesThem()
	{
		field.setText("cow");
		assertTrue(suggestionList.isVisible());
		assertEquals(2, suggestionList.getModel().getSize());

		field.setText("");
		assertFalse(suggestionList.isVisible());
	}

	@Test
	public void enterAddsExactlyWhatWasTypedWhenNothingIsHighlighted()
	{
		field.setText("Cow*");
		field.postActionEvent();

		assertEquals(Collections.singletonList(Collections.singletonList("Cow*")), changes);
		assertEquals("", field.getText());
	}

	@Test
	public void arrowKeysAndEnterPickASuggestion()
	{
		field.setText("cow");
		press(KeyEvent.VK_DOWN);
		press(KeyEvent.VK_DOWN);
		field.postActionEvent();

		assertEquals(Collections.singletonList(Collections.singletonList("Cow calf")), changes);
	}

	@Test
	public void upFromTheFirstSuggestionGoesBackToTheTypedText()
	{
		field.setText("cow");
		press(KeyEvent.VK_DOWN);
		press(KeyEvent.VK_UP);
		field.postActionEvent();

		assertEquals(Collections.singletonList(Collections.singletonList("cow")), changes);
	}

	@Test
	public void escapeClosesTheSuggestions()
	{
		field.setText("cow");
		press(KeyEvent.VK_ESCAPE);

		assertFalse(suggestionList.isVisible());
		assertEquals("cow", field.getText());
	}

	@Test
	public void namesAlreadyListedAreNotSuggestedOrAddedTwice()
	{
		field.setText("Cow");
		field.postActionEvent();
		field.setText("cow");
		assertEquals(1, suggestionList.getModel().getSize());
		assertEquals("Cow calf", suggestionList.getModel().getElementAt(0));

		field.postActionEvent();
		assertEquals(1, changes.size());
		assertEquals("", field.getText());
	}

	@Test
	public void theRemoveButtonDropsTheEntry()
	{
		editor.setEntries(Arrays.asList("Goblin", "Rat"));
		List<Component> buttons = new ArrayList<>();
		collect(editor, JButton.class, buttons);
		assertEquals(2, buttons.size());

		((JButton) buttons.get(0)).doClick();

		assertEquals(Collections.singletonList(Collections.singletonList("Rat")), changes);
		assertEquals(Collections.singletonList("Rat"), editor.getEntries());
	}

	@Test
	public void entriesFromTheSettingsPageDoNotEchoBack()
	{
		editor.setEntries(Arrays.asList("Goblin"));

		assertTrue(changes.isEmpty());
		assertEquals(Arrays.asList("Goblin"), editor.getEntries());
	}
}

