	@Test
	public void containsIgnoresCaseAndPadding()
	{
		assertTrue(NameList.contains(Arrays.asList("Goblin"), " goblin "));
		assertFalse(NameList.contains(Arrays.asList("Goblin"), "Gob"));
	}
